// 1. Callback
setTimeout(() => {
  console.log("Callback finished");
}, 1000);

// 2. Promise
const promise = new Promise(resolve => {
  setTimeout(() => resolve("Promise finished"), 1000);
});

promise.then(result => {
  console.log(result);
});

// 3. async/await
async function example() {
  const result = await promise;
  console.log(result);
}

example();

